    pub const INVALID_RESIZE_EDGE: Self = Self(0);
    /// Invalid parent toplevel.
    pub const INVALID_PARENT: Self = Self(1);
    /// Client provided an invalid min or max size.
    pub const INVALID_SIZE: Self = Self(2);
