static XDG_POPUP_REQUEST_GRAB_TYPES: [Option<&Interface>; 2] = [Some(&super::wayland::WL_SEAT_INTERFACE), None];
static XDG_POPUP_REQUEST_REPOSITION_TYPES: [Option<&Interface>; 2] = [Some(&XDG_POSITIONER_INTERFACE), None];
static XDG_POPUP_REQUESTS: [Message; 3] = [
    Message::new(c"destroy", c"", &[]),
    Message::new(c"grab", c"ou", &XDG_POPUP_REQUEST_GRAB_TYPES),
    Message::new(c"reposition", c"3ou", &XDG_POPUP_REQUEST_REPOSITION_TYPES),
];
static XDG_POPUP_EVENT_CONFIGURE_TYPES: [Option<&Interface>; 4] = [None, None, None, None];
static XDG_POPUP_EVENT_REPOSITIONED_TYPES: [Option<&Interface>; 1] = [None];
static XDG_POPUP_EVENTS: [Message; 3] = [
    Message::new(c"configure", c"iiii", &XDG_POPUP_EVENT_CONFIGURE_TYPES),
    Message::new(c"popup_done", c"", &[]),
    Message::new(c"repositioned", c"3u", &XDG_POPUP_EVENT_REPOSITIONED_TYPES),
];

/// The `xdg_popup` interface's table (libwayland's `wl_interface`).
pub static XDG_POPUP_INTERFACE: Interface =
    Interface::new(c"xdg_popup", 7, &XDG_POPUP_REQUESTS, &XDG_POPUP_EVENTS, Some(0));

/// Short-lived, popup surfaces for menus. A popup surface is a short-lived, temporary surface. It can be used to
/// implement for example menus, popovers, tooltips and other similar user interface concepts.
#[derive(Debug)]
pub struct XdgPopup(Proxy);

impl Object for XdgPopup {
    const INTERFACE: &'static Interface = &XDG_POPUP_INTERFACE;
    fn from_proxy(proxy: Proxy) -> Self {
        XdgPopup(proxy)
    }
    fn proxy(&self) -> &Proxy {
        &self.0
    }
}

impl XdgPopup {
    /// Remove xdg_popup interface. This destroys the popup. Explicitly destroying the xdg_popup object will also
    /// dismiss the popup, and unmap the surface.
    pub fn destroy(self) {
        self.0.destroy_with(0, &[]);
    }

    /// Make the popup take an explicit grab. This request makes the created popup take an explicit grab. An explicit
    /// grab will be dismissed when the user dismisses the popup, or when the client destroys the xdg_popup.
    ///
    /// - `seat`: the wl_seat of the user event.
    /// - `serial`: the serial of the user event.
    pub fn grab(&self, seat: &super::wayland::WlSeat, serial: u32) {
        self.0.send(1, &[Arg::Object(Some(seat.proxy())), Arg::Uint(serial)]);
    }

    /// Recalculate the popup's location. Reposition an already-mapped popup. The popup will be placed given the details
    /// in the passed xdg_positioner object, and a xdg_popup.repositioned followed by xdg_popup.configure and
    /// xdg_surface.configure will be emitted in response.
    ///
    /// Since version 3.
    /// (Not sent to an object of an older version: what it makes is then none.)
    ///
    /// - `token`: reposition request token.
    pub fn reposition(&self, positioner: &XdgPositioner, token: u32) {
        self.0.send(2, &[Arg::Object(Some(positioner.proxy())), Arg::Uint(token)]);
    }
}

/// The `xdg_popup` interface's events.
#[derive(Debug)]
pub enum XdgPopupEvent {
    /// Configure the popup surface. This event asks the popup surface to configure itself given the configuration. The
    /// configured state should not be applied immediately.
    Configure {
        /// X position relative to parent surface window geometry.
        x: i32,
        /// Y position relative to parent surface window geometry.
        y: i32,
        /// Window geometry width.
        width: i32,
        /// Window geometry height.
        height: i32,
    },
    /// Popup interaction is done. The popup_done event is sent out when a popup is dismissed by the compositor. The
    /// client should destroy the xdg_popup object at this point.
    PopupDone,
    /// Signal the completion of a repositioned request. The repositioned event is sent as part of a popup configuration
    /// sequence, together with xdg_popup.configure and lastly xdg_surface.configure to notify the completion of a
    /// reposition request.
    ///
    /// Since version 3.
    Repositioned {
        /// Reposition request token.
        token: u32,
    },
}

impl XdgPopupEvent {
    /// Event `opcode`'s arguments decoded (none if they aren't its).
    pub fn decode(opcode: u16, args: &mut Args) -> Option<Self> {
        let _ = &args;
        Some(match opcode {
            0 => Self::Configure { x: args.int()?, y: args.int()?, width: args.int()?, height: args.int()? },
            1 => Self::PopupDone,
            2 => Self::Repositioned { token: args.uint()? },
            _ => return None,
        })
    }
}

/// `xdg_popup.error`'s values.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub struct XdgPopupError(pub u32);

impl XdgPopupError {
    /// Tried to grab after being mapped.
    pub const INVALID_GRAB: Self = Self(0);
}
